(function(){
const E=s=>String(s??"").replace(/[&<>]/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;"}[m]));
const N=(id,x,y,w,title,sub,kind="power")=>({id,x,y,w,h:74,title,sub,kind});
const G=(from,to,via=[],dir="forward",kind="power")=>({from,to,via,dir,kind});
const ports=(n)=>({l:[n.x,n.y+n.h/2],r:[n.x+n.w,n.y+n.h/2],t:[n.x+n.w/2,n.y],b:[n.x+n.w/2,n.y+n.h]});
function resolve(map,r){const [id,p]=r.split(".");if(!map[id]||!ports(map[id])[p])throw Error("无效端口 "+r);return ports(map[id])[p]}
function linear(t){
 const stages=t.id==="totem-pole"?["AC 输入","Fuse / MOV / EMI","Boost 电感","Totem-Pole 功率桥","400V DC-Link"]:t.stages;
 const n=stages.length,g=24,w=Math.max(112,Math.min(150,(1100-g*(n-1))/n)),total=w*n+g*(n-1),x0=(1200-total)/2,y=142;
 const nodes=stages.map((s,i)=>N("n"+i,x0+i*(w+g),y,w,s,i===0?t.direction:i===n-1?"负载 / 下一级":"功率子系统",i===n-1?"load":"power"));
 const bi=t.direction.includes("⇄"),edges=nodes.slice(0,-1).map((n,i)=>G(n.id+".r",nodes[i+1].id+".l",[],bi?"bidir":"forward"));
 return{nodes,edges,surge:(nodes.find(n=>/保护|SPD|MOV|Fuse|保险丝|EMI/.test(n.title))||nodes[0]).id+".t",note:"主功率路径按模块端口连接；箭头表示能量方向，红色虚线表示外部瞬态耦合位置。"}
}
function ups(t){return{nodes:[N("ac",45,142,125,"市电输入","AC"),N("pfc",220,142,130,"PFC 整流","AC → DC"),N("dc",405,142,130,"DC-Link","400/800V"),N("inv",590,142,135,"PWM 逆变器","DC → AC"),N("lcl",780,142,125,"LCL 滤波","正弦输出"),N("load",1035,142,125,"关键负载","受保护","load"),N("bat",300,275,130,"电池组","Fuse · BMS","branch"),N("bdc",500,275,155,"双向电池 DC/DC","充电 / 放电","branch"),N("bypass",405,28,155,"静态旁路 STS","市电直供","branch")],edges:[G("ac.r","pfc.l"),G("pfc.r","dc.l"),G("dc.r","inv.l"),G("inv.r","lcl.l"),G("lcl.r","load.l"),G("bat.r","bdc.l",[],"bidir"),G("bdc.t","dc.b",[[577,245],[470,245]],"bidir"),G("ac.t","bypass.l",[[107,65]],"forward"),G("bypass.r","load.t",[[970,65],[1097,65]])],surge:"ac.t",note:"双变换主通道、电池双向支路与静态旁路分别建模；旁路不经过 DC-Link 和逆变器。"}}
function hotSwap(t){return{nodes:[N("a",45,75,120,"输入 A","48/54V"),N("b",45,245,120,"输入 B","48/54V"),N("pa",230,75,135,"Fuse / TVS A","独立保护"),N("pb",230,245,135,"Fuse / TVS B","独立保护"),N("oa",430,75,140,"ORing FET A","防反灌"),N("ob",430,245,140,"ORing FET B","防反灌"),N("hs",690,160,145,"Hot-Swap FET","浪涌限流"),N("bulk",900,160,110,"Bulk 电容","受控充电"),N("load",1060,160,100,"机架负载","受保护","load")],edges:[G("a.r","pa.l"),G("b.r","pb.l"),G("pa.r","oa.l"),G("pb.r","ob.l"),G("oa.r","hs.l",[[620,112],[620,197]]),G("ob.r","hs.l",[[620,282],[620,197]]),G("hs.r","bulk.l"),G("bulk.r","load.l")],surge:"pa.t",surge2:"pb.t",note:"A/B 两路在 ORing 后汇合，Hot-Swap 位于公共母线；两路输入没有被错误串联。"}}
function parallelPfc(t){const inter=t.id==="interleaved-pfc";return{nodes:[N("in",45,160,135,"AC 输入","Fuse · SPD"),N("front",230,160,135,inter?"整流桥":"EMI 滤波","公共前端"),N("pa",455,65,175,inter?"PFC 相 A":"正半周 Boost",inter?"LA · QA · DA":"L1 · Q1 · D1","branch"),N("pb",455,255,175,inter?"PFC 相 B":"负半周 Boost",inter?"LB · QB · DB":"L2 · Q2 · D2","branch"),N("sum",745,160,140,"汇流节点",inter?"180° 交错":"半周换向"),N("dc",1010,160,145,"400V DC-Link","CDC","load")],edges:[G("in.r","front.l"),G("front.r","pa.l",[[410,197],[410,102]]),G("front.r","pb.l",[[410,197],[410,292]]),G("pa.r","sum.l",[[685,102],[685,197]]),G("pb.r","sum.l",[[685,292],[685,197]]),G("sum.r","dc.l")],surge:"in.t",note:"两条 Boost 功率通道并联汇流；A/B 相或正/负半周通道不是前后串联级。"}}
function motor(t){return{nodes:[N("ac",45,150,135,"三相 AC","SPD · EMI"),N("rect",235,150,140,"整流 / AFE","AC → DC"),N("dc",440,150,140,"DC-Link","CDC"),N("vsi",710,150,145,"三相 VSI","Q1–Q6"),N("m",1020,150,125,"电机","U / V / W","load"),N("br",440,275,140,"制动支路","QBR · RBR","branch")],edges:[G("ac.r","rect.l"),G("rect.r","dc.l"),G("dc.r","vsi.l"),G("vsi.r","m.l"),G("dc.b","br.t",[],"forward","branch")],surge:"ac.t",note:"制动单元并联在 DC-Link 上吸收回馈能量，不串入整流器与逆变器之间。"}}
function vrm(t){return{nodes:[N("in",65,150,150,"12/48V 输入","Hot-Swap · Cin"),N("phase",360,150,190,"多相功率级 ×N","DrMOS + L/TLVR"),N("co",710,150,155,"输出电容阵列","低 ESR / 低 ESL"),N("load",1020,150,130,"GPU / CPU","0.6–1.8V","load"),N("ctl",360,275,190,"多相 PWM 控制器","均流 · 遥感","control")],edges:[G("in.r","phase.l"),G("phase.r","co.l"),G("co.r","load.l"),G("ctl.t","phase.b",[],"forward","control")],surge:"in.t",note:"PWM 控制器通过控制线驱动各相，不串入主能量路径；N 相功率级并联汇流。"}}
function model(t){if(t.id==="online-ups")return ups(t);if(t.id==="hot-swap-oring")return hotSwap(t);if(["interleaved-pfc","bridgeless-pfc"].includes(t.id))return parallelPfc(t);if(t.id==="motor-drive")return motor(t);if(t.id==="multiphase-vrm")return vrm(t);return linear(t)}
function edgeSvg(map,e,id){const a=resolve(map,e.from),b=resolve(map,e.to),pts=[a,...e.via,b],d=pts.map((p,i)=>(i?"L":"M")+p[0]+" "+p[1]).join("");const markers=e.dir==="bidir"?`marker-start="url(#back${id})" marker-end="url(#next${id})"`:e.kind==="control"?"":`marker-end="url(#next${id})"`;return`<path class="${e.kind==="control"?"control":"power-wire"}" ${markers} d="${d}"/>`}
function nodeSvg(n){return`<g class="module ${n.kind==="load"?"protected":""} ${n.kind}"><rect x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" rx="3"/><circle class="port" cx="${n.x}" cy="${n.y+n.h/2}" r="3"/><circle class="port" cx="${n.x+n.w}" cy="${n.y+n.h/2}" r="3"/><circle class="port" cx="${n.x+n.w/2}" cy="${n.y}" r="3"/><circle class="port" cx="${n.x+n.w/2}" cy="${n.y+n.h}" r="3"/><text class="title" x="${n.x+n.w/2}" y="${n.y+31}">${E(n.title)}</text><text class="sub" x="${n.x+n.w/2}" y="${n.y+53}">${E(n.sub)}</text></g>`}
function validate(m){const map=Object.fromEntries(m.nodes.map(n=>[n.id,n])),errors=[];m.edges.forEach((e,i)=>{try{resolve(map,e.from);resolve(map,e.to)}catch(x){errors.push("E"+i+":"+x.message)}});const seen=new Set();m.edges.forEach((e,i)=>{const k=e.from+"→"+e.to;if(seen.has(k))errors.push("重复连线 "+k);seen.add(k)});return{map,errors}}
function render(t){const m=model(t),v=validate(m),id=("m"+t.id).replace(/\W/g,"");const defs=`<defs><marker id="next${id}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#0e607e"/></marker><marker id="back${id}" markerWidth="8" markerHeight="8" refX="1" refY="4" orient="auto"><path d="M8 0L0 4L8 8Z" fill="#0e607e"/></marker><marker id="surge${id}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#d94732"/></marker></defs>`;const target=resolve(v.map,m.surge),surge=`<path class="surge" marker-end="url(#surge${id})" d="M${target[0]} 24V${target[1]-7}"/><text class="red-label" x="${Math.max(28,target[0]-64)}" y="18">外部瞬态入口</text>`+(m.surge2?(()=>{const p=resolve(v.map,m.surge2);return`<path class="surge" marker-end="url(#surge${id})" d="M${p[0]+44} 24V${p[1]-34}H${p[0]}V${p[1]-7}"/>`})():"");return`<svg class="diagram system-svg matlab-system" viewBox="0 0 1200 390" data-system-model="${E(t.id)}" data-link-errors="${v.errors.length}" aria-label="${E(t.name)} MATLAB风格系统架构图">${defs}<rect class="model-canvas" x="16" y="8" width="1168" height="366"/>${m.edges.map(e=>edgeSvg(v.map,e,id)).join("")}${m.nodes.map(nodeSvg).join("")}${surge}<g class="connectivity ${v.errors.length?"bad":""}"><rect x="930" y="28" width="220" height="30" rx="3"/><text x="1040" y="48">${v.errors.length?"连接错误 "+v.errors.length:"端口连线校验通过"}</text></g><text class="label system-note" x="36" y="354">${E(m.note)}</text></svg>`}
window.renderProfessionalSystem=render;
window.auditSystemModels=()=>window.POWER_TOPOLOGIES.map(t=>{const v=validate(model(t));return{id:t.id,errors:v.errors}});
})();
